import logging
import secrets

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        self._stock = stock

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        try:
            reservation_id = self._stock.reserve(item, quantity)
        except Exception as exc:
            ref = secrets.token_hex(8)
            logger.error(
                "Unexpected error while placing order (ref=%s, user=%s, item=%s, quantity=%s)",
                ref,
                user,
                item,
                quantity,
                exc_info=True,
            )
            if is_admin:
                detail = f"{type(exc).__name__}: {exc}"
            else:
                detail = "Please try again later."
            return 500, (
                f"Sorry, something went wrong while processing your order. "
                f"Reference code: {ref}. {detail}"
            )
        return 200, (
            f"Thank you, {user}! Your order of {quantity} x '{item}' "
            f"has been reserved (reservation id: {reservation_id})."
        )
